import {ATLAS_KEY,ADVENTURE_KEY,REGIONS,MISSIONS,THEMES} from './atlas-data.js';
import {newAtlas,restoreAtlas,regionState,atlasStats,currentRegion,nextMission,missionInfo,claimCode,choosePath,buyTheme,configureMission,syncExpedition,availableStoryPages} from './atlas-core.js';
import {restoreGame} from './engine.js';
import {icon,atlasEmblem,worldMap,sceneArt,guardianArt} from './atlas-art.js';

const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const views=[['atlas','compass','Atlas'],['historia','book','Crónica'],['misiones','seal','Misiones'],['memorias','grid','Memorias'],['guardian','person','Guardián'],['expediciones','sword','Expediciones']];
let state,legacy=null,saveOK=true;
try{legacy=restoreGame(JSON.parse(localStorage.getItem(ADVENTURE_KEY)));}catch{}
try{state=restoreAtlas(JSON.parse(localStorage.getItem(ATLAS_KEY)));}catch{saveOK=false;}
state??=newAtlas(legacy?.name);
state.reducedMotion ||= window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let view=views.some(v=>v[0]===location.hash.slice(1))?location.hash.slice(1):'atlas';
let selected=currentRegion(state).id,missionFilter='all',memoryFilter='all',collection='memories',modalOpen=false,returnFocus=null,toastTimer;
const imported=syncExpedition(state,legacy);

function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon));}
function save(){try{localStorage.setItem(ATLAS_KEY,JSON.stringify(state));saveOK=true;}catch{saveOK=false;}updateSaveLabel();}
function updateSaveLabel(){$('storageStatus').innerHTML=saveOK?'<b></b> Guardado en este dispositivo':'Guardado no disponible · exporta tu Atlas';}
function toast(message){clearTimeout(toastTimer);$('atlasToast').textContent=message;$('atlasToast').classList.remove('hidden');toastTimer=setTimeout(()=>$('atlasToast').classList.add('hidden'),4800);}
function levelPercent(stats){return stats.nextLevel?Math.min(100,(stats.xp-stats.levelStart)/(stats.nextLevel-stats.levelStart)*100):100;}
function renderHeader(){
  const stats=atlasStats(state);$('atlasApp').dataset.theme=state.theme;
  document.body.style.backgroundColor=({verdigris:'#102b2a',ambar:'#302d27',lunar:'#242d38',aurora:'#143435'})[state.theme];
  document.documentElement.classList.toggle('reduced-motion',state.reducedMotion);
  $('railEmblem').innerHTML=atlasEmblem();
  $('mainNav').innerHTML=views.map(([id,i,label])=>`<button class="rail-button ${view===id?'active':''}" data-view="${id}" ${view===id?'aria-current="page"':''}>${icon(i)}<small>${label}</small></button>`).join('');
  $('lightBalance').innerHTML=`${icon('light')} ${stats.light}<small>luz</small>`;
  $('profileBtn').innerHTML=`<span class="avatar-mini">${guardianArt(state.look,stats.companion)}</span><span><strong>${esc(state.name)}</strong><small>Nv. ${stats.level} · ${stats.rank}</small><span class="mini-xp"><i style="width:${levelPercent(stats)}%"></i></span></span>`;
  updateSaveLabel();hydrate();
}
function intro(eyebrow,title,text,extra=''){return `<div class="page-intro"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${text}</p></div>${extra}</div>`;}
function counter(){return `<div class="chapter-counter"><strong>${String(atlasStats(state).restored).padStart(2,'0')}</strong><small>DE CINCO<br>TERRITORIOS DESPIERTOS</small></div>`;}
function rewardLine(m){return `<div class="rewards-inline"><span>${icon('spark')} ${m.xp} experiencia</span><span>${icon('light')} ${m.light} luz</span></div>`;}
function regionTabs(){return `<div class="region-tabs">${REGIONS.map(r=>`<button class="region-tab ${selected===r.id?'active':''} ${regionState(state,r.id).unlocked?'':'locked'}" data-action="select-region" data-id="${r.id}">${icon(r.icon)}${r.short}</button>`).join('')}</div>`;}
function storyButton(r,status){return status.restored?'Volver a esta historia':status.count>=2&&!status.choice?'Elegir un futuro':status.count?'Continuar la crónica':'Leer el primer recuerdo';}
function chapterCard(r){
  const status=regionState(state,r.id),previous=REGIONS[REGIONS.indexOf(r)-1];
  return `<article class="chapter-card"><div class="chapter-image">${sceneArt(r.id,status.restored?2:0,status.choice?.id)}<span class="chapter-number">${r.number}</span></div><div class="chapter-card-body"><span class="eyebrow">${status.restored?'UN LUGAR QUE VUELVE A VIVIR':status.unlocked?'TU CRÓNICA EN ESTE TERRITORIO':'UNA HISTORIA BAJO EL SILENCIO'}</span><h2>${r.chapter}</h2><p>${r.description}</p><div class="chapter-progress">${[0,1,2,3].map(i=>`<i class="${i<status.count?'filled':''}"></i>`).join('')}</div><span class="chapter-progress-label">${status.count} / 4 memorias · ${status.choice?'Una decisión escrita':status.count>=2?'Una decisión te espera':'La historia se revela contigo'}</span>${status.choice?`<div class="choice-note">${icon(status.choice.icon)}<span>${status.choice.title}<br>Una huella de tu decisión.</span></div>`:''}${status.unlocked?`<button class="primary-button" data-action="story" data-id="${r.id}">${storyButton(r,status)} ${icon('arrow')}</button>`:`<span class="chapter-lock">${icon('lock')} Despierta primero ${previous.short.toLowerCase()}.</span>`}</div></article>`;
}
function home(){
  const r=REGIONS.find(r=>r.id===selected),active=currentRegion(state),next=nextMission(state),status=regionState(state,active.id),stats=atlasStats(state);
  return intro('TU HISTORIA CONTINÚA','El mundo recuerda contigo.','Cada desafío deja una huella. Cada decisión, una historia.',counter())+`<div class="hero-layout"><section class="map-panel" aria-label="Mapa del reino"><div class="map-panel-top"><span class="map-top-label">${icon('compass')} EL REINO DE AURALIA</span><span class="eyebrow">${stats.memories} / 20 MEMORIAS</span></div>${worldMap(state,selected)}${stats.restored===5?'<span class="world-complete-ribbon">✦ AURALIA HA RECUPERADO SUS COLORES</span>':''}<div class="map-pin-legend"><span><i class="legend-dot living"></i> Recuerdos recuperados</span><span><i class="legend-dot selected"></i> Tu siguiente huella</span><span><i class="legend-dot"></i> Por despertar</span></div></section>${chapterCard(r)}</div><div class="section-heading"><h2>Tus próximas huellas</h2><p>Un mismo Atlas.<br>Distintas formas de avanzar.</p></div><div class="trail-grid"><article class="trail-card"><div class="trail-icon">${icon(next?'seal':'feather')}</div><div class="trail-card-copy"><span class="eyebrow">${next?'UN DESAFÍO DEL AULA':stats.restored===5?'TU LEGADO':'UNA DECISIÓN PENDIENTE'}</span><h3>${next?esc(missionInfo(state,next.id).title):stats.restored===5?'El reino lleva tu nombre':'Decide qué volverá a vivir'}</h3><p>${next?'Tu actividad recupera una memoria del territorio.':stats.restored===5?'Vuelve a recorrer las historias que construiste.':'Ya reuniste las cuatro memorias. Escribe el futuro de este lugar.'}</p><button class="quiet-button" data-action="${next?'mission':'story'}" data-id="${next?.id||active.id}">${next?'Ver mi actividad':'Abrir la crónica'} ${icon('arrow')}</button></div></article><article class="trail-card"><div class="trail-icon">${icon('grid')}</div><div class="trail-card-copy"><span class="eyebrow">TU COLECCIÓN</span><h3>${stats.memories} recuerdos que permanecen</h3><p>Las memorias y las reliquias cuentan el camino que has recorrido.</p><button class="quiet-button" data-view="memorias">Abrir mis memorias ${icon('arrow')}</button></div></article><article class="trail-card"><div class="trail-icon">${icon('sword')}</div><div class="trail-card-copy"><span class="eyebrow">MÁS ALLÁ DEL ATLAS</span><h3>El bosque te está llamando</h3><p>Explora, resuelve y enfrenta al guardián. Tus hallazgos vuelven contigo.</p><button class="quiet-button" data-view="expediciones">Ver la expedición ${icon('arrow')}</button></div></article></div><div class="button-row"><button class="quiet-button" data-action="teacher">${icon('feather')} Guía docente y códigos de prueba</button><span class="subtle">Prototipo · cada Atlas se guarda en su navegador.</span></div>`;
}
function missionsPage(){
  const r=REGIONS.find(r=>r.id===selected),status=regionState(state,r.id);
  const list=MISSIONS.filter(m=>m.region===selected&&(missionFilter==='all'||(missionFilter==='done')===state.completed.includes(m.id)));
  return intro('EL AULA DEJA SU HUELLA','Misiones que despiertan lugares.','Realiza tu actividad y canjea el sello que recibas. La memoria permanecerá contigo.')+regionTabs()+(!status.unlocked?`<p class="notice">${r.name} todavía duerme. Recupera el territorio anterior para comenzar sus misiones.</p>`:'')+`<div class="section-heading"><h2>${r.name}</h2><div class="filters">${[['all','Todas'],['pending','Pendientes'],['done','Recuperadas']].map(([id,label])=>`<button class="filter-button ${missionFilter===id?'active':''}" data-action="mission-filter" data-id="${id}">${label}</button>`).join('')}</div></div><div class="mission-grid">${list.map(m=>{const info=missionInfo(state,m.id),done=state.completed.includes(m.id);return `<article class="mission-card ${done?'done':''}"><div class="mission-card-top"><span class="mission-number">${r.number} · 0${m.index+1}</span><span class="pill ${done?'complete':''}">${done?icon('check'):icon(r.icon)} ${done?'Recuerdo recuperado':m.label}</span></div><h3>${esc(info.title)}</h3><p>${esc(info.prompt)}</p>${rewardLine(m)}<div class="button-row"><button class="${done?'secondary-button':'primary-button'}" data-action="${done?'memory':'mission'}" data-id="${m.id}">${done?'Ver mi memoria':'Abrir actividad'} ${icon(done?'book':'arrow')}</button></div></article>`;}).join('')}</div>${!list.length?'<div class="empty-state"><h3>Todavía no hay huellas aquí.</h3><p>Cuando recuperes una memoria, aparecerá en esta sección.</p></div>':''}`;
}
function chroniclePage(){
  const decisions=REGIONS.filter(r=>regionState(state,r.id).choice);
  return intro('LAS HISTORIAS QUE DECIDIMOS CONTINUAR','La crónica de tu Auralia.','Cinco capítulos. Dos futuros por territorio. Tus decisiones permanecen en el mundo.')+`<div class="chronicle-grid">${REGIONS.map(r=>{const status=regionState(state,r.id);return `<article class="chronicle-card ${status.unlocked?'':'locked'}">${sceneArt(r.id,status.restored?2:0,status.choice?.id)}<div class="chronicle-body"><span class="eyebrow">CAPÍTULO ${r.number} · ${status.restored?'RESTAURADO':status.unlocked?'EN TU CAMINO':'POR DESPERTAR'}</span><h3>${r.chapter}</h3><p>${r.description}</p><button class="secondary-button" data-action="story" data-id="${r.id}" ${status.unlocked?'':'disabled'}>${icon(status.unlocked?'book':'lock')} ${status.unlocked?'Abrir capítulo':'Historia dormida'}</button></div></article>`;}).join('')}</div><div class="section-heading"><h2>Lo que cambió por ti</h2><p>La huella de tus decisiones.</p></div>${decisions.length?`<div class="decision-list">${decisions.map(r=>{const c=regionState(state,r.id).choice;return `<article class="decision-row">${icon(c.icon)}<div><small>${r.name.toUpperCase()}</small><h3>${c.title}</h3><p>${c.effect}</p></div></article>`;}).join('')}</div>`:'<div class="empty-state">'+icon('feather')+'<h3>Tu primera decisión está por llegar.</h3><p>Recupera dos memorias del bosque. Nara te mostrará dos formas de reconstruir Valdeluz.</p></div>'}`;
}
function memoriesPage(){
  const stats=atlasStats(state);
  let content='';
  if(collection==='memories'){
    const list=MISSIONS.filter(m=>memoryFilter==='all'||(memoryFilter==='found')===state.completed.includes(m.id));
    content=`<div class="section-heading"><h2>${stats.memories} / 20 memorias</h2><div class="filters">${[['all','Todas'],['found','Reveladas'],['missing','Por revelar']].map(([id,label])=>`<button class="filter-button ${memoryFilter===id?'active':''}" data-action="memory-filter" data-id="${id}">${label}</button>`).join('')}</div></div><div class="memory-grid">${list.map(m=>{const found=state.completed.includes(m.id),r=REGIONS.find(r=>r.id===m.region);return `<button class="memory-card ${found?'':'locked'}" data-action="memory" data-id="${m.id}"><div class="memory-illustration">${found?sceneArt(r.id,m.index===3?2:0,regionState(state,r.id).choice?.id):icon(r.icon)}<span class="memory-no">${r.number} · 0${m.index+1}</span></div><div class="memory-card-body"><span class="eyebrow">${r.name.toUpperCase()}</span><h3>${found?m.memory:'Un recuerdo por revelar'}</h3></div></button>`;}).join('')}</div>${!list.length?'<div class="empty-state"><h3>Esta página espera su primer recuerdo.</h3><p>Un sello o una expedición pueden dejar aquí su huella.</p></div>':''}`;
  }else content=`<div class="relic-grid">${REGIONS.map(r=>{const found=regionState(state,r.id).restored||(r.id==='bosque'&&state.expeditionEvents.includes('gauntlet'));return `<article class="relic-card ${found?'':'locked'}"><div class="relic-icon">${icon(r.id==='bosque'?'root':r.icon)}</div><h3>${r.relic}</h3><p>${r.relicDescription}</p><span class="pill ${found?'complete':''}">${found?'Registrada en tu Atlas':'Por recuperar'}</span></article>`;}).join('')}</div><p class="notice" style="margin-top:20px">Cada territorio restaurado conserva su reliquia. Las habilidades del prototipo de exploración se obtienen dentro de esa expedición.</p>`;
  return intro('LO QUE ENCONTRASTE VIAJA CONTIGO','Tu archivo de lo imposible.','Una colección de memorias y reliquias que hace visible todo lo que has construido.')+`<div class="collection-toggle"><button class="region-tab ${collection==='memories'?'active':''}" data-action="collection" data-id="memories">${icon('grid')} Memorias</button><button class="region-tab ${collection==='relics'?'active':''}" data-action="collection" data-id="relics">${icon('root')} Reliquias</button></div>${content}`;
}
function guardianPage(){
  const stats=atlasStats(state);
  return intro('QUIEN LLEVA EL ATLAS','Tu historia también te transforma.','La experiencia reconoce tu recorrido. La luz te permite dar una identidad propia a tu Atlas.')+`<div class="profile-layout"><section class="guardian-panel"><span class="eyebrow">EL GUARDIÁN DEL ATLAS</span>${guardianArt(state.look,stats.companion)}<h2>${esc(state.name)}</h2><p>${stats.rank}</p><span class="level-lozenge">NIVEL ${stats.level}</span></section><section class="profile-content"><h2>El nombre de tu aventura</h2><form id="profileForm" class="profile-form"><div><label for="guardianName">Nombre o apodo</label><input id="guardianName" class="text-input" value="${esc(state.name)}" maxlength="24" autocomplete="off"></div><button class="primary-button" type="submit">Guardar nombre</button></form><div class="look-options">${[['bosque','Bosque','#719279'],['marea','Marea','#6d96a2'],['sol','Alba','#bfa073']].map(([id,label,color])=>`<button class="look-button ${state.look===id?'active':''}" data-action="look" data-id="${id}"><span class="look-dot" style="background:${color}"></span>${label}</button>`).join('')}</div><div class="profile-stats"><div class="profile-stat"><strong>${stats.xp}</strong><small>EXPERIENCIA</small></div><div class="profile-stat"><strong>${stats.memories}</strong><small>MEMORIAS</small></div><div class="profile-stat"><strong>${stats.light}</strong><small>LUZ DISPONIBLE</small></div></div><div class="level-progress"><span style="width:${levelPercent(stats)}%"></span></div><p class="level-progress-caption">${stats.nextLevel?`${stats.nextLevel-stats.xp} de experiencia hasta el nivel ${stats.level+1}`:'Has alcanzado el último nivel del prototipo.'}</p><div class="companion-panel">${icon('spark')}<div><h3>${stats.companion}, tu compañero de luz</h3><p>${stats.companion==='Chispa'?'Una pequeña presencia que crece contigo. Al reunir 300 de experiencia, despertará una nueva forma.':stats.companion==='Lumen'?'La chispa aprendió a volar. Al reunir 760 de experiencia, conservará una forma astral.':'Tu compañero conserva la luz de todas las historias que has recuperado.'}</p></div></div></section></div><div class="section-heading"><h2>La forja del Atlas</h2><p>La luz cambia su aspecto.<br>Tu historia conserva su valor.</p></div><div class="shop-grid">${THEMES.map(t=>{const owned=t.cost===0||state.purchases.includes(t.id),equipped=state.theme===t.id;return `<article class="theme-card"><div class="theme-sample" style="color:${t.color}">${icon('compass')}</div><h3>${t.name}</h3><p>${t.description}</p><span class="theme-cost">${icon('light')} ${owned?'En tu colección':t.cost+' de luz'}</span><button class="secondary-button" data-action="theme" data-id="${t.id}" ${equipped?'disabled':''}>${equipped?'Equipado':owned?'Equipar':'Tejer acabado'}</button></article>`;}).join('')}</div><div class="settings-box"><div><h3>Conserva tu recorrido.</h3><p>El Atlas se guarda en este navegador. Exporta una copia para trasladar tu historia a otro dispositivo.</p></div><div class="button-row"><button class="secondary-button" data-action="export">${icon('download')} Exportar Atlas</button><button class="secondary-button" data-action="import">${icon('upload')} Importar copia</button></div></div><div class="button-row"><button class="quiet-button" data-action="help">${icon('settings')} Ayuda y opciones</button><button class="quiet-button" data-action="teacher">${icon('feather')} Guía docente</button></div>`;
}
function expeditionsPage(){return intro('OTRA PUERTA AL MISMO UNIVERSO','Hay historias que se recorren.','El Atlas conserva el progreso. Las expediciones te invitan a salir, explorar y encontrarlo.')+`<section class="expedition-feature">${sceneArt('bosque',0)}<div class="expedition-details"><span class="eyebrow">EXPEDICIÓN 01 · PROTOTIPO JUGABLE</span><h2>El primer recuerdo</h2><p>Vuelve a Valdeluz, entra en el bosque y encuentra el Santuario de la Raíz. Los acertijos, la exploración y el guardián pertenecen a esta aventura.</p><div class="expedition-tags"><span class="pill">Vista cenital</span><span class="pill">Exploración y combate</span><span class="pill">10–15 minutos</span></div><a class="primary-button" href="expedicion/">Entrar a la expedición ${icon('arrow')}</a><p class="subtle" style="margin:16px 0 0">Al volver, el Atlas registra tus hallazgos automáticamente en este mismo navegador. La partida de exploración conserva su propio guardado.</p></div></section><div class="section-heading"><h2>Lo que vuelve contigo</h2><p>Una recompensa por hallazgo.<br>Sin duplicaciones al regresar.</p></div><div class="expedition-rewards"><article class="expedition-reward">${icon('root')}<h3>Guante de Raíces</h3><p>La reliquia se registra en tu colección. Recibes 20 de experiencia y 10 de luz.</p><span class="pill ${state.expeditionEvents.includes('gauntlet')?'complete':''}">${state.expeditionEvents.includes('gauntlet')?'Registrado en el Atlas':'Encuéntralo en el bosque'}</span></article><article class="expedition-reward">${icon('seal')}<h3>La misión del umbral</h3><p>Recuperar el Eco completa la tercera misión del bosque: 70 de experiencia, 22 de luz y una memoria.</p><span class="pill ${state.completed.includes('bosque-3')?'complete':''}">${state.completed.includes('bosque-3')?'Misión ya registrada':'Recupera el Eco del Bosque'}</span></article><article class="expedition-reward">${icon('leaf')}<h3>La semilla de Valdeluz</h3><p>El secreto del jardín añade un hallazgo especial, 20 de experiencia y 8 de luz.</p><span class="pill ${state.expeditionEvents.includes('seed')?'complete':''}">${state.expeditionEvents.includes('seed')?'Secreto registrado':'Un jardín espera tu regreso'}</span></article></div><div class="future-expedition">${icon('compass')}<p><strong>Más encuentros, un mismo Atlas.</strong>El núcleo admite nuevas expediciones y misiones. Los otros cuatro territorios ya tienen crónica y recompensas; sus mundos de exploración quedan para una siguiente etapa.</p></div>`;}
function render(){renderHeader();$('content').innerHTML=({atlas:home,historia:chroniclePage,misiones:missionsPage,memorias:memoriesPage,guardian:guardianPage,expediciones:expeditionsPage})[view]();hydrate($('content'));document.title=`${views.find(v=>v[0]===view)[2]} · Atlas de Ecos`;const form=$('profileForm');if(form)form.onsubmit=e=>{e.preventDefault();state.name=$('guardianName').value.trim().slice(0,24)||'Guardián';save();render();toast('El Atlas conserva tu nombre.');};}
function navigate(id){if(!views.some(v=>v[0]===id))return;view=id;history.replaceState(null,'','#'+id);render();window.scrollTo({top:0,behavior:'instant'});}
function openModal(html,{wide=false,focusId}={}){
  if(!modalOpen)returnFocus=document.activeElement;modalOpen=true;
  $('atlasModal').classList.toggle('wide',wide);$('modalBody').innerHTML=html;$('atlasModalBackdrop').classList.remove('hidden');$('content').inert=true;document.querySelector('.rail').inert=true;document.querySelector('.topbar').inert=true;document.body.style.overflow='hidden';$('atlasModal').scrollTop=0;hydrate($('modalBody'));
  requestAnimationFrame(()=>($(focusId)||$('closeModal')).focus({preventScroll:true}));
}
function closeModal(){modalOpen=false;$('atlasModalBackdrop').classList.add('hidden');$('content').inert=false;document.querySelector('.rail').inert=false;document.querySelector('.topbar').inert=false;document.body.style.overflow='';if(returnFocus?.isConnected)returnFocus.focus({preventScroll:true});else $('content').focus({preventScroll:true});}
function showCode(){
  openModal(`<div class="modal-pad"><span class="eyebrow">UNA ACTIVIDAD. UNA NUEVA HUELLA.</span><h2 id="modalHeading">El Atlas reconoce tu esfuerzo.</h2><p>Introduce el sello que recibiste al completar tu actividad. Recuperarás una memoria, experiencia y luz.</p><form id="codeForm"><label class="modal-input-label" for="atlasCode">Código del sello</label><input id="atlasCode" class="text-input code-input" placeholder="AUR-BOS-01" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="50"><div id="codeError" class="form-error" role="status"></div><div class="modal-actions"><button type="submit" class="primary-button">${icon('seal')} Recuperar mi recompensa</button><button type="button" class="secondary-button" data-action="teacher">Ver códigos de prueba</button></div></form><p class="subtle" style="margin:20px 0 0">Prototipo local: los códigos muestran cómo se conectan las actividades y el juego. La entrega y evaluación de actividades las decide el docente.</p></div>`,{focusId:'atlasCode'});
  $('codeForm').onsubmit=e=>{e.preventDefault();const result=claimCode(state,$('atlasCode').value);if(!result.ok){$('codeError').textContent=result.message;return;}selected=result.mission.region;save();render();showReward(result);};
}
function showReward(result){
  const m=result.mission,r=REGIONS.find(r=>r.id===m.region),status=regionState(state,r.id);
  openModal(`<div class="modal-pad reward-pad"><span class="eyebrow">UNA MEMORIA VUELVE A VIVIR</span><h2 id="modalHeading">Tu huella cambia el mapa.</h2><div class="reward-card">${sceneArt(r.id,m.index===3?2:0,status.choice?.id)}<h3>${m.memory}</h3></div>${rewardLine(m)}<p class="reward-lore">${r.name} conserva una nueva parte de su historia.</p>${result.newlyRestored?`<div class="reward-bonus">✦ Territorio restaurado · reliquia recuperada · +50 experiencia · +25 luz</div>`:''}<div class="modal-actions"><button class="primary-button" data-action="${status.count>=2&&!status.choice?'story':'close'}" data-id="${r.id}">${status.count>=2&&!status.choice?'Elegir el futuro de este lugar':'Guardar en mi Atlas'} ${icon('arrow')}</button><button class="secondary-button" data-action="reward-map">Ver el mapa</button></div></div>`);
}
function showMission(id){const m=missionInfo(state,id);if(!m)return;const r=REGIONS.find(r=>r.id===m.region),done=state.completed.includes(id),status=regionState(state,r.id);openModal(`<div class="modal-pad"><span class="eyebrow">${r.name.toUpperCase()} · ${m.label.toUpperCase()}</span><h2 id="modalHeading">${esc(m.title)}</h2><p>${esc(m.prompt)}</p>${rewardLine(m)}<p class="notice">${done?'Esta actividad ya dejó su memoria en tu Atlas.':status.unlocked?'Realiza la actividad indicada por tu docente. Cuando recibas el código, vuelve para recuperar tu recompensa.':'Este territorio todavía duerme. Conserva el código hasta despertar la región anterior.'}</p><div class="modal-actions"><button class="primary-button" data-action="${done?'memory':'code'}" data-id="${id}" ${status.unlocked?'':'disabled'}>${done?'Abrir memoria':'Ya tengo mi sello'} ${icon('arrow')}</button><button class="secondary-button" data-action="close">Volver al Atlas</button></div>${id==='bosque-3'&&!done?'<p class="subtle" style="margin-top:20px">También puedes completar esta misión recuperando el Eco del Bosque en la expedición cenital.</p>':''}</div>`);}
function showMemory(id){const m=MISSIONS.find(m=>m.id===id);if(!m)return;const r=REGIONS.find(r=>r.id===m.region),found=state.completed.includes(id);if(!found){showMission(id);return;}openModal(`<div class="modal-scene">${sceneArt(r.id,m.index===3?2:0,regionState(state,r.id).choice?.id)}<span class="story-chapter-label">MEMORIA ${r.number} · 0${m.index+1}</span></div><div class="story-body"><span class="story-speaker">${icon(r.icon)} ${r.name.toUpperCase()}</span><h2 id="modalHeading">${m.memory}</h2><p class="story-text">${[r.story[0].text,r.story[1].text,'Al cruzar un umbral, un lugar que parecía lejano empieza a formar parte de tu propia historia.',r.story[2].text][m.index]}</p><p class="subtle">Recuperada con «${esc(missionInfo(state,id).title)}». Esta memoria permanece en tu colección.</p><div class="modal-actions"><button class="primary-button" data-action="close">Conservar este recuerdo</button><button class="secondary-button" data-action="story" data-id="${r.id}">Abrir su capítulo</button></div></div>`);}
function showStory(id,page){
  const r=REGIONS.find(r=>r.id===id),status=regionState(state,id);if(!r||!status.unlocked){toast('Esta historia espera a que despiertes el territorio anterior.');return;}
  const available=availableStoryPages(state,id);
  if(!Number.isInteger(page)||!available.includes(page))page=status.count>=2&&!status.choice?1:status.restored?2:0;
  const scene=r.story[page],previous=REGIONS[REGIONS.indexOf(r)-1],previousChoice=previous?regionState(state,previous.id).choice:null;
  const readId=id+'-'+page;if(!state.read.includes(readId)){state.read.push(readId);save();}
  openModal(`<div class="modal-scene">${sceneArt(id,page,status.choice?.id)}<span class="story-chapter-label">CAPÍTULO ${r.number} · ${r.chapter.toUpperCase()}</span></div><div class="story-body"><span class="story-speaker">${icon(r.icon)} ${scene.speaker.toUpperCase()}</span><h2 id="modalHeading">${scene.title}</h2><p class="story-text">${scene.text}</p>${page===0&&previousChoice?`<p class="story-context">Tu viaje llega desde ${previousChoice.title}. Su recuerdo acompaña este nuevo capítulo.</p>`:''}${page===1?(status.choice?`<div class="chosen-path">${icon(status.choice.icon)}<div><h3>${status.choice.title}</h3><p>${status.choice.effect}</p></div></div><p class="subtle">Esta decisión ya forma parte de tu Auralia.</p>`:`<div class="choice-grid">${r.choices.map(c=>`<button class="story-choice" data-action="choose" data-id="${id}" data-choice="${c.id}">${icon(c.icon)}<strong>${c.title}</strong><small>${c.description}</small><span class="choice-cta">Escribir este futuro →</span></button>`).join('')}</div><p class="subtle">Ambos caminos tienen valor. El lugar y su recuerdo conservarán tu decisión.</p>`):''}${page===2&&status.choice?`<p class="story-context">${status.choice.effect}</p><p class="notice">${atlasStats(state).restored===5?'Tu Atlas conserva las cinco historias y las decisiones que les dieron forma.':'Territorio restaurado. Una nueva ruta está disponible en el mapa.'}</p>`:''}<div class="story-navigation"><div class="story-dots">${[0,1,2].map(i=>`<button data-action="story-page" data-id="${id}" data-page="${i}" class="${i===page?'active':''}" aria-label="Escena ${i+1}" ${available.includes(i)?'':'disabled'}></button>`).join('')}</div><span class="story-page-number">${page+1} / 3 ESCENAS · ${status.count} / 4 MEMORIAS</span>${available.includes(page+1)?`<button class="primary-button" data-action="story-page" data-id="${id}" data-page="${page+1}">Continuar ${icon('arrow')}</button>`:`<button class="secondary-button" data-action="close">Volver a mi Atlas</button>`}</div>${page===0&&status.count<2?'<p class="subtle" style="margin:16px 0 0">Recupera dos memorias de este territorio para revelar su decisión.</p>':''}${page===1&&status.choice&&status.count<4?'<p class="subtle" style="margin:16px 0 0">Recupera las cuatro memorias para despertar el territorio y descubrir su desenlace.</p>':''}</div>`);
}
function showTeacher(regionId=selected){
  const r=REGIONS.find(r=>r.id===regionId)||REGIONS[0];
  openModal(`<div class="modal-pad"><span class="eyebrow">DISEÑO Y REVISIÓN DOCENTE</span><h2 id="modalHeading">Un núcleo para todo el recorrido.</h2><p>El Atlas conserva las recompensas y la historia de cada estudiante. Las actividades del aula y los encuentros de exploración aportan a ese mismo recorrido.</p><div class="teacher-intro">${[['01 · ACTIVIDAD','El aula','Tú decides el desafío y los criterios para entregar el sello.'],['02 · RECOMPENSA','El Atlas','El código añade experiencia, luz y una memoria única.'],['03 · DECISIÓN','La crónica','Dos memorias abren una elección que deja una huella en el mundo.'],['04 · LEGADO','El reino','Cuatro memorias y una decisión restauran un territorio.']].map(([n,title,text])=>`<div class="teacher-flow"><small>${n}</small><strong>${title}</strong><p>${text}</p></div>`).join('')}</div><p class="notice"><strong>Prototipo local:</strong> los códigos son públicos, no verifican entregas y no hay seguimiento compartido entre estudiantes. Puedes adaptar el texto de las actividades de esta copia. Las cuentas y el registro docente remoto serían una siguiente etapa.</p><div class="teacher-select-row"><label for="teacherRegion">Territorio</label><select id="teacherRegion" class="select-input">${REGIONS.map(t=>`<option value="${t.id}" ${r.id===t.id?'selected':''}>${t.name}</option>`).join('')}</select></div><table class="teacher-code-table"><thead><tr><th>ACTIVIDAD Y RECOMPENSA</th><th>CÓDIGO</th><th>AJUSTAR</th></tr></thead><tbody>${MISSIONS.filter(m=>m.region===r.id).map(m=>`<tr><td>${esc(missionInfo(state,m.id).title)}<small>${m.xp} experiencia · ${m.light} luz · una memoria</small></td><td><code>${m.code}</code></td><td><button class="table-action" data-action="configure" data-id="${m.id}">Editar</button></td></tr>`).join('')}</tbody></table><p class="subtle">Los territorios se abren en orden. Los códigos de actividades pueden canjearse en cualquier orden dentro del territorio activo. Volver a usar un código no duplica premios.</p><div class="review-box"><h3>Prueba la lógica en esta partida</h3><p>Estos botones añaden progreso real al Atlas local de revisión. Para ver la transformación, completa las cuatro actividades y elige el futuro del capítulo.</p><div class="button-row"><button class="primary-button" data-action="demo-one">${icon('seal')} Probar una recompensa</button><button class="secondary-button" data-action="demo-chapter">${icon('book')} Preparar una decisión y su desenlace</button></div></div><div class="section-heading"><h3>El puente con las expediciones</h3></div><p>La aventura cenital se conserva en <strong>Expediciones → El primer recuerdo</strong>. Encontrar el guante y la semilla añade hallazgos; recuperar el Eco completa la tercera misión del bosque. Al regresar, el Atlas importa estos logros una sola vez, en el mismo navegador.</p><div class="modal-actions"><button class="secondary-button" data-action="close">Volver a la revisión</button><button class="secondary-button" data-action="export">${icon('download')} Exportar esta configuración</button></div></div>`,{wide:true});
  $('teacherRegion').onchange=e=>showTeacher(e.target.value);
}
function showConfigure(id){const m=missionInfo(state,id);if(!m)return;openModal(`<div class="modal-pad"><span class="eyebrow">ACTIVIDAD ${m.code}</span><h2 id="modalHeading">Tu desafío, dentro de Auralia.</h2><p>Adapta la consigna a tu asignatura. El código y la recompensa se conservan. Este cambio pertenece a esta copia del Atlas.</p><form id="missionConfig"><label class="modal-input-label" for="missionTitle">Nombre de la actividad</label><input id="missionTitle" class="text-input" maxlength="90" value="${esc(m.title)}"><label class="modal-input-label" for="missionPrompt" style="margin-top:15px">Consigna</label><textarea id="missionPrompt" class="text-area" maxlength="600">${esc(m.prompt)}</textarea><div class="modal-actions"><button class="primary-button" type="submit">Guardar actividad</button><button class="secondary-button" type="button" data-action="config-reset" data-id="${id}">Recuperar texto original</button></div></form></div>`);$('missionConfig').onsubmit=e=>{e.preventDefault();configureMission(state,id,$('missionTitle').value,$('missionPrompt').value);save();render();showTeacher(m.region);toast('La consigna quedó guardada en esta copia del Atlas.');};}
function showHelp(){openModal(`<div class="modal-pad"><span class="eyebrow">DOS FORMAS DE VIVIR UNA MISMA HISTORIA</span><h2 id="modalHeading">Tu Atlas te acompaña.</h2><p><strong>Atlas:</strong> el mapa recupera color con cada memoria. Cuatro memorias y una decisión despiertan cada territorio.</p><p><strong>Crónica:</strong> una aventura gráfica con cinco capítulos y decisiones que cambian los lugares que reconstruyes.</p><p><strong>Misiones:</strong> actividades de clase que entregan recuerdos, experiencia y luz. Tu docente decide cómo conseguir sus sellos.</p><p><strong>Expediciones:</strong> aventuras de exploración y combate. Sus hallazgos pueden completar misiones del Atlas.</p><div class="settings-line"><div><label for="reduceMotion">Reducir movimiento</label><p>Desactiva animaciones del Atlas.</p></div><input id="reduceMotion" type="checkbox" ${state.reducedMotion?'checked':''}></div><p class="notice">Guardado automático local. Si borras los datos del navegador, pierdes esta copia. Exporta tu Atlas para conservarlo o trasladarlo. La expedición tiene su propio guardado y todavía no se incluye en esta exportación.</p><div class="modal-actions"><button class="secondary-button" data-action="export">${icon('download')} Exportar Atlas</button><button class="secondary-button" data-action="import">${icon('upload')} Importar copia</button><button class="secondary-button" data-action="teacher">${icon('feather')} Guía docente</button><button class="secondary-button danger-button" data-action="reset">Reiniciar este Atlas</button></div></div>`);$('reduceMotion').onchange=e=>{state.reducedMotion=e.target.checked;save();renderHeader();};}
function exportAtlas(){const file=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download='Mi_Atlas_de_Ecos.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Tu copia incluye el Atlas y las consignas configuradas.');}
function sync(){try{legacy=restoreGame(JSON.parse(localStorage.getItem(ADVENTURE_KEY)));}catch{return;}const messages=syncExpedition(state,legacy);if(messages.length){save();render();toast(messages.join(' · '));}}

document.addEventListener('click',e=>{
  const nav=e.target.closest('[data-view]');if(nav){if(modalOpen)closeModal();navigate(nav.dataset.view);return;}
  const target=e.target.closest('[data-region]');if(target){selected=target.dataset.region;render();return;}
  const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id}=b.dataset;
  switch(action){
    case 'close':closeModal();break;
    case 'reward-map':closeModal();navigate('atlas');break;
    case 'code':showCode();break;
    case 'story':showStory(id);break;
    case 'story-page':showStory(id,Number(b.dataset.page));break;
    case 'choose':{const result=choosePath(state,id,b.dataset.choice);if(!result.ok){toast(result.message);break;}save();render();showStory(id,result.newlyRestored?2:1);toast(result.newlyRestored?'Tu decisión despertó el territorio. +50 experiencia · +25 luz':result.choice.effect);break;}
    case 'mission':showMission(id);break;
    case 'memory':showMemory(id);break;
    case 'select-region':selected=id;render();break;
    case 'mission-filter':missionFilter=id;render();break;
    case 'memory-filter':memoryFilter=id;render();break;
    case 'collection':collection=id;render();break;
    case 'look':if(['bosque','marea','sol'].includes(id)){state.look=id;save();render();}break;
    case 'theme':{const result=buyTheme(state,id);if(!result.ok){toast(result.message);break;}save();render();toast(result.purchased?'La luz tejió un nuevo acabado para tu Atlas.':'Tu Atlas ya lleva este acabado.');break;}
    case 'teacher':showTeacher();break;
    case 'configure':showConfigure(id);break;
    case 'config-reset':configureMission(state,id,'','');save();render();showConfigure(id);break;
    case 'demo-one':{const m=nextMission(state);if(!m){toast('Este capítulo espera tu decisión. Abre su crónica.');break;}const result=claimCode(state,m.code);if(result.ok){selected=m.region;save();render();showReward(result);}break;}
    case 'demo-chapter':{const r=currentRegion(state);for(const m of MISSIONS.filter(m=>m.region===r.id&&!state.completed.includes(m.id)))claimCode(state,m.code);selected=r.id;save();render();showStory(r.id,regionState(state,r.id).choice?2:1);break;}
    case 'help':showHelp();break;
    case 'export':exportAtlas();break;
    case 'import':$('importFile').click();break;
    case 'reset':openModal(`<div class="modal-pad"><span class="eyebrow">VOLVER A LA PRIMERA PÁGINA</span><h2 id="modalHeading">¿Comenzar otro Atlas?</h2><p>Se reemplazará el progreso y la configuración local del Atlas. La partida de la expedición se conservará y sus hallazgos volverán a registrarse. Puedes exportar primero una copia.</p><div class="modal-actions"><button class="secondary-button" data-action="export">Exportar antes</button><button class="primary-button" data-action="reset-confirm">Comenzar otro Atlas</button></div></div>`);break;
    case 'reset-confirm':state=newAtlas();syncExpedition(state,legacy);save();selected='bosque';closeModal();navigate('atlas');toast('El Atlas abre una nueva página.');break;
  }
});
$('closeModal').onclick=closeModal;$('atlasModalBackdrop').onclick=e=>{if(e.target===$('atlasModalBackdrop'))closeModal();};$('codeBtn').onclick=showCode;$('profileBtn').onclick=()=>navigate('guardian');$('teacherBtn').onclick=()=>showTeacher();$('helpBtn').onclick=showHelp;
document.addEventListener('keydown',e=>{
  if(modalOpen){if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const f=[...$('atlasModal').querySelectorAll('button:not(:disabled),input:not(:disabled),textarea,select,a[href]')].filter(x=>!x.hidden),first=f[0],last=f.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}return;}
  const target=e.target.closest('[data-region]');if(target&&['Enter',' '].includes(e.key)){e.preventDefault();selected=target.dataset.region;render();}
});
$('importFile').onchange=async e=>{
  const file=e.target.files[0];e.target.value='';if(!file)return;
  if(file.size>1000000){toast('La copia es demasiado grande para un Atlas de este prototipo.');return;}
  let restored;try{restored=restoreAtlas(JSON.parse(await file.text()));}catch{}
  if(!restored){toast('El archivo no contiene una copia válida de este Atlas.');return;}
  openModal(`<div class="modal-pad"><span class="eyebrow">UNA HISTORIA QUE REGRESA</span><h2 id="modalHeading">Recuperar el Atlas de ${esc(restored.name)}.</h2><p>La copia contiene ${atlasStats(restored).memories} memorias y ${atlasStats(restored).restored} territorios restaurados. Reemplazará el Atlas de este navegador. La partida de la expedición se conserva aparte.</p><div class="modal-actions"><button id="confirmImport" class="primary-button">Recuperar esta historia</button><button class="secondary-button" data-action="close">Conservar mi Atlas actual</button></div></div>`);
  $('confirmImport').onclick=()=>{state=restored;save();selected=currentRegion(state).id;closeModal();navigate('atlas');toast('Tu historia vuelve a estar contigo.');};
};
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(views.some(x=>x[0]===v)){view=v;render();}});
window.addEventListener('storage',e=>{if(e.key===ADVENTURE_KEY)sync();else if(e.key===ATLAS_KEY){try{const updated=restoreAtlas(JSON.parse(e.newValue));if(updated){state=updated;render();}}catch{}}});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync();});window.addEventListener('pageshow',sync);
save();render();if(imported.length)toast(imported.length===1?'Tu expedición dejó un nuevo hallazgo en el Atlas.':'Tu expedición dejó '+imported.length+' hallazgos en el Atlas.');
